function largest(...numbers) {
  if (numbers.length === 0) return null;
  let max = numbers[0];
  for (const n of numbers) {
    if (n > max) max = n;
  }
  return max;
}

console.log(largest(3, 9, 4), largest(-5, -1), largest());

